import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// The Gallery preview harness builds each demo under a namespaced base path so
// several published apps can be served side by side. Locally the base is '/'.
export default defineConfig({
  base: process.env.GALLERY_PREVIEW_BASE ?? '/',
  plugins: [react()],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
});

